    // Phase 5.C.4 commit 37: MissingTool eligibility tests.
    // Pro: "tf_proto grpc path not implemented vs grpc path
    // implemented but grpc_cpp_plugin missing — these are
    // different. The first is a Rush migration gap. The
    // second is host setup."

    #[test]
    fn eligibility_missing_tool_blocks_dispatch_when_shape_supported() {
        // Allowlisted rule + supported shape + missing tool:
        // MissingTool fires.
        let d = compute_scheduler_eligibility(
            "tf_proto_library",
            true,
            None,
            Some("grpc_cpp_plugin"),
            2,
        );
        assert!(!d.eligible);
        assert_eq!(
            d.reason,
            SchedulerEligibilityReason::MissingTool("grpc_cpp_plugin")
        );
    }

    #[test]
    fn eligibility_unsupported_shape_wins_over_missing_tool() {
        // When both fire, UnsupportedShape wins. Rationale:
        // even installing the tool wouldn't unblock dispatch
        // if the shape's migration hasn't landed. The
        // migration gap is more fundamental than the install
        // gap.
        let d = compute_scheduler_eligibility(
            "tf_proto_library",
            true,
            Some("grpc shape not migrated"),
            Some("grpc_cpp_plugin"),
            2,
        );
        assert!(!d.eligible);
        assert_eq!(
            d.reason,
            SchedulerEligibilityReason::UnsupportedShape(
                "grpc shape not migrated"
            )
        );
    }

    #[test]
    fn eligibility_missing_tool_wins_over_action_graph_incomplete() {
        // MissingTool reports the install-gap reason even
        // when the action graph is also incomplete (which it
        // typically would be — analyze() may have skipped
        // ExecutableAction population because the tool was
        // missing).
        let d = compute_scheduler_eligibility(
            "tf_proto_library",
            false,
            None,
            Some("grpc_cpp_plugin"),
            2,
        );
        assert!(!d.eligible);
        assert_eq!(
            d.reason,
            SchedulerEligibilityReason::MissingTool("grpc_cpp_plugin")
        );
    }

    #[test]
    fn eligibility_missing_tool_loses_to_rule_kind_unverified() {
        // If the rule kind isn't on the allowlist, MissingTool
        // is moot — the rule itself is the gate.
        let d = compute_scheduler_eligibility(
            "genrule",
            true,
            None,
            Some("some_tool"),
            2,
        );
        assert!(!d.eligible);
        assert_eq!(d.reason, SchedulerEligibilityReason::RuleKindUnverified);
    }

    #[test]
    fn eligibility_unsupported_shape_carries_static_reason() {
        // Reason string round-trips through the variant. Future
        // diagnostic surfaces (UI, telemetry) can match on the
        // static str to identify which shape gate fired.
        const R1: &str = "shape A unverified";
        const R2: &str = "shape B unverified";
        let d1 = compute_scheduler_eligibility("cc_library", true, Some(R1), None, 2);
        let d2 = compute_scheduler_eligibility("cc_library", true, Some(R2), None, 2);
        match (d1.reason, d2.reason) {
            (
                SchedulerEligibilityReason::UnsupportedShape(s1),
                SchedulerEligibilityReason::UnsupportedShape(s2),
            ) => {
                assert_eq!(s1, R1);
                assert_eq!(s2, R2);
                assert_ne!(s1, s2);
            }
            (a, b) => panic!(
                "expected UnsupportedShape on both, got {:?} and {:?}",
                a, b
            ),
        }
    }

    // Phase 5.C.4 commit 206 (Batch AA): no-action scheduler
    // target invariant tests. Pin the behavior Pro's 5.C.5
    // pilot relies on for header-only cc_library targets like
    // //tensorflow/core/platform:macros.

    #[test]
    fn no_action_scheduler_target_completes() {
        // Allowlisted rule kind + supported shape + tools
        // available + zero declared actions →
        // NoDeclaredActions, eligible=true. The classifier
        // accepts the no-op outcome rather than routing the
        // target to legacy build() via ActionGraphIncomplete.
        let d = compute_scheduler_eligibility(
            "cc_library",
            /*in_action_eligible_set*/ false,
            None,
            None,
            /*declared_action_count*/ 0,
        );
        assert!(
            d.eligible,
            "zero-action allowlisted target must be scheduler-eligible (no-op), got {:?}",
            d.reason
        );
        assert_eq!(d.reason, SchedulerEligibilityReason::NoDeclaredActions);
    }

    #[test]
    fn no_action_target_not_legacy_required_for_own_actions() {
        // The invariant Pro's commit-206 spec names: a
        // zero-action target must NOT be reported as a
        // legacy fallback for its own actions. With
        // NoDeclaredActions{eligible=true}, the orchestrator
        // routes the target through
        // execute_target_actions_via_scheduler (which returns
        // Ok(empty) for zero declared actions) — NOT through
        // node.rule_instance.build(). The invocation report
        // records it in the zero_action_scheduler_targets
        // bucket, not the legacy_invoked Vec.
        let mut report = crate::legacy_scheduler_report::LegacyVsSchedulerInvocationReport::new();
        report.record_scheduler_dispatch(
            "//tensorflow/core/platform:macros",
            "cc_library",
            0,
        );
        assert_eq!(report.scheduler_count, 1);
        assert_eq!(report.legacy_count, 0);
        assert_eq!(report.zero_action_count, 1);
        assert!(
            report.legacy_invoked.is_empty(),
            "zero-action target must not appear in legacy fallbacks, found {:?}",
            report.legacy_invoked
        );
        assert!(
            report
                .zero_action_scheduler_targets
                .contains(&"//tensorflow/core/platform:macros".to_string())
        );
    }

    #[test]
    fn zero_action_target_has_zero_output_validation_checks() {
        // Output validation walks declared actions; a target
        // with zero declared actions naturally produces zero
        // validation checks. This isn't a special-case in the
        // validation pass — it's the natural consequence of
        // "iterate over an empty set." The invariant: the
        // count of validation checks for a zero-action target
        // is exactly 0, NOT a failure.
        //
        // We test the underlying contract: when the
        // action_count_by_target map reports 0 for a target,
        // the eligibility classifier returns NoDeclaredActions
        // (eligible=true). The validation pass that comes
        // later in the orchestrator only walks declared
        // actions — there are no declared actions to validate.
        let d = compute_scheduler_eligibility(
            "cc_library",
            false,
            None,
            None,
            0, // zero actions
        );
        // The eligibility classifier doesn't fire
        // ActionGraphIncomplete (the gate that *would* turn
        // into a "validation could not run" report).
        assert_ne!(
            d.reason,
            SchedulerEligibilityReason::ActionGraphIncomplete,
            "zero-action target must not be classified as \
             ActionGraphIncomplete — that would imply the \
             validation pass should warn about missing data."
        );
        // No declared actions means no validation checks; the
        // checks-count is 0, and 0 is not a failure.
        assert!(d.eligible);
    }

    #[test]
    fn providers_visible_to_dependents() {
        // Public providers come from PASS A's analyze()
        // output, not from PASS B's dispatch path. The
        // invariant: scheduler-dispatched (NoDeclaredActions)
        // and legacy-fallback targets BOTH have their
        // providers visible to dependents because the
        // built_providers HashMap is populated by analyze().
        //
        // We can't reach the built_providers map from a
        // unit test (it requires running the orchestrator),
        // but we CAN assert the invocation report doesn't
        // remove or hide a target's identity based on the
        // dispatch path — both buckets carry the label so
        // downstream tooling that joins the report against
        // the providers map gets a consistent view.
        let mut report = crate::legacy_scheduler_report::LegacyVsSchedulerInvocationReport::new();
        report.record_scheduler_dispatch("//pkg:header_only", "cc_library", 0);
        report.record_scheduler_dispatch("//pkg:with_actions", "cc_library", 2);
        report.record_legacy_invocation(
            "//pkg:legacy",
            "gentbl_cc_library",
            "RuleKindUnverified",
        );
        // All three labels appear somewhere in the report —
        // the dispatch path doesn't erase the target's
        // identity.
        let mut all_labels: Vec<&str> = report
            .scheduler_dispatched
            .iter()
            .map(|e| e.label.as_str())
            .chain(report.legacy_invoked.iter().map(|e| e.label.as_str()))
            .collect();
        all_labels.sort();
        assert_eq!(
            all_labels,
            vec![
                "//pkg:header_only",
                "//pkg:legacy",
                "//pkg:with_actions",
            ]
        );
    }

    // Phase 5.C.4 commit 38: scheduler preflight report tests.
    // These cover bucketing logic, the is_complete() invariant,
    // determinism (HashMap → Vec sort), and format output shape.

    fn mk_decision(reason: SchedulerEligibilityReason) -> SchedulerEligibility {
        let eligible = matches!(reason, SchedulerEligibilityReason::RuleKindVerified);
        SchedulerEligibility { eligible, reason }
    }

    #[test]
    fn preflight_buckets_decisions_by_reason() {
        let decisions = vec![
            (
                "cc_library".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
            (
                "cc_library".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
            (
                "genrule".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindUnverified),
            ),
            (
                "tf_proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::UnsupportedShape(
                    "grpc not migrated",
                )),
            ),
            (
                "tf_proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::MissingTool(
                    "grpc_cpp_plugin",
                )),
            ),
            (
                "proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::ActionGraphIncomplete),
            ),
        ];
        let report = scheduler_preflight(&decisions);
        assert_eq!(report.dispatched, 2);
        assert_eq!(report.total_targets, 6);
        assert_eq!(report.rule_kind_unverified, vec![mk_rk("genrule", 1)]);
        assert_eq!(
            report.unsupported_shape,
            vec![mk_us("tf_proto_library", "grpc not migrated", 1)]
        );
        assert_eq!(report.missing_tool, vec![mk_mt("grpc_cpp_plugin", 1)]);
        assert_eq!(
            report.action_graph_incomplete,
            vec![mk_rk("proto_library", 1)]
        );
    }

    #[test]
    fn preflight_dispatched_count_matches_rule_kind_verified() {
        let decisions = vec![
            (
                "cc_library".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
            (
                "cc_binary".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
            (
                "cc_test".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
        ];
        let report = scheduler_preflight(&decisions);
        assert_eq!(report.dispatched, 3);
        assert_eq!(report.total_targets, 3);
        assert!(report.rule_kind_unverified.is_empty());
        assert!(report.unsupported_shape.is_empty());
        assert!(report.missing_tool.is_empty());
        assert!(report.action_graph_incomplete.is_empty());
    }

    #[test]
    fn preflight_is_complete_when_all_decisions_classified() {
        let decisions = vec![
            (
                "cc_library".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
            (
                "genrule".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindUnverified),
            ),
        ];
        let report = scheduler_preflight(&decisions);
        assert!(report.is_complete());
    }

    #[test]
    fn preflight_is_complete_on_empty_input() {
        let report = scheduler_preflight(&[]);
        assert_eq!(report.dispatched, 0);
        assert_eq!(report.total_targets, 0);
        assert!(report.is_complete());
    }

    #[test]
    fn preflight_unsupported_shape_grouped_by_rule_type_and_reason() {
        // Two distinct (rule_type, reason) pairs should produce
        // two separate bucket entries; identical pairs should
        // collapse to a single entry with count == 2.
        let decisions = vec![
            (
                "tf_proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::UnsupportedShape(
                    "grpc not migrated",
                )),
            ),
            (
                "tf_proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::UnsupportedShape(
                    "grpc not migrated",
                )),
            ),
            (
                "tf_proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::UnsupportedShape(
                    "services not migrated",
                )),
            ),
        ];
        let report = scheduler_preflight(&decisions);
        // sorted by (rule_type, reason); both share rule_type so
        // sort key is the reason string.
        assert_eq!(
            report.unsupported_shape,
            vec![
                mk_us("tf_proto_library", "grpc not migrated", 2),
                mk_us("tf_proto_library", "services not migrated", 1),
            ]
        );
    }

    #[test]
    fn preflight_buckets_are_deterministic_across_runs() {
        // Same input set in different orders should produce
        // identical reports (sorted Vec output, not HashMap
        // iteration order).
        let mut a = vec![
            (
                "cc_library".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindVerified),
            ),
            (
                "genrule".to_string(),
                mk_decision(SchedulerEligibilityReason::RuleKindUnverified),
            ),
            (
                "tf_proto_library".to_string(),
                mk_decision(SchedulerEligibilityReason::MissingTool(
                    "grpc_cpp_plugin",
                )),
            ),
        ];
        let report_a = scheduler_preflight(&a);
        a.reverse();
        let report_b = scheduler_preflight(&a);
        assert_eq!(report_a.rule_kind_unverified, report_b.rule_kind_unverified);
        assert_eq!(report_a.unsupported_shape, report_b.unsupported_shape);
        assert_eq!(report_a.missing_tool, report_b.missing_tool);
        assert_eq!(
            report_a.action_graph_incomplete,
            report_b.action_graph_incomplete
        );
    }

    fn mk_rk(rk: &str, n: usize) -> RuleKindCount {
        RuleKindCount {
            rule_kind: rk.to_string(),
            count: n,
        }
    }
    fn mk_us(rk: &str, reason: &str, n: usize) -> UnsupportedShapeCount {
        UnsupportedShapeCount {
            rule_kind: rk.to_string(),
            reason: reason.to_string(),
            count: n,
        }
    }
    fn mk_mt(tool: &str, n: usize) -> MissingToolCount {
        MissingToolCount {
            tool: tool.to_string(),
            count: n,
        }
    }

