    #[test]
    fn preflight_json_uses_named_fields_and_schema_version() {
        let report = SchedulerPreflightReport {
            schema_version: SCHEDULER_PREFLIGHT_SCHEMA_VERSION,
            dispatched: 8,
            rule_kind_unverified: vec![mk_rk("gentbl_cc_library", 2)],
            unsupported_shape: vec![mk_us(
                "tf_proto_library",
                "grpc not verified",
                1,
            )],
            missing_tool: vec![mk_mt("grpc_cpp_plugin", 1)],
            action_graph_incomplete: vec![mk_rk("proto_library", 1)],
            external_repo_source_missing: vec![],
            total_targets: 13,
        };
        let json = format_preflight_report_json(&report).expect("ok");
        let parsed: serde_json::Value =
            serde_json::from_str(&json).expect("re-parse");
        assert_eq!(parsed["schema_version"], 1);
        assert_eq!(parsed["dispatched"], 8);
        assert_eq!(parsed["total_targets"], 13);
        // Named fields, not positional tuples.
        assert_eq!(
            parsed["rule_kind_unverified"][0]["rule_kind"],
            "gentbl_cc_library"
        );
        assert_eq!(parsed["rule_kind_unverified"][0]["count"], 2);
        assert_eq!(
            parsed["unsupported_shape"][0]["rule_kind"],
            "tf_proto_library"
        );
        assert_eq!(
            parsed["unsupported_shape"][0]["reason"],
            "grpc not verified"
        );
        assert_eq!(parsed["unsupported_shape"][0]["count"], 1);
        assert_eq!(parsed["missing_tool"][0]["tool"], "grpc_cpp_plugin");
        assert_eq!(parsed["missing_tool"][0]["count"], 1);
        assert_eq!(
            parsed["action_graph_incomplete"][0]["rule_kind"],
            "proto_library"
        );
        assert_eq!(parsed["action_graph_incomplete"][0]["count"], 1);
    }

