    // Phase 5.C.4 commit 56: SchedulerSupportLevel JSON
    // shape pinning. The canonical type lives in rush-rules
    // (next to RequiredTool); these tests verify it
    // serializes consistently with commit 54b's enum
    // normalization style.

    #[test]
    fn support_level_serializes_with_tagged_payload_shape() {
        use rush_rules::{RequiredTool, SchedulerSupportLevel};

        let v = SchedulerSupportLevel::Verified;
        let parsed: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&v).unwrap()).unwrap();
        assert_eq!(parsed["kind"], "verified");
        assert!(parsed["data"].is_null());

        let u = SchedulerSupportLevel::RuleKindUnverified;
        let parsed: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&u).unwrap()).unwrap();
        assert_eq!(parsed["kind"], "rule_kind_unverified");

        let s = SchedulerSupportLevel::UnsupportedShape { reason: "grpc" };
        let parsed: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&s).unwrap()).unwrap();
        assert_eq!(parsed["kind"], "unsupported_shape");
        assert_eq!(parsed["data"]["reason"], "grpc");

        let m = SchedulerSupportLevel::MissingTool {
            tool: RequiredTool::Protoc,
        };
        let parsed: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&m).unwrap()).unwrap();
        assert_eq!(parsed["kind"], "missing_tool");
        // RequiredTool also serializes snake_case (commit 56).
        assert_eq!(parsed["data"]["tool"], "protoc");

        let a = SchedulerSupportLevel::ActionGraphIncomplete;
        let parsed: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&a).unwrap()).unwrap();
        assert_eq!(parsed["kind"], "action_graph_incomplete");

        let l = SchedulerSupportLevel::LegacyRequired {
            reason: "header pseudo-rule",
        };
        let parsed: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&l).unwrap()).unwrap();
        assert_eq!(parsed["kind"], "legacy_required");
        assert_eq!(parsed["data"]["reason"], "header pseudo-rule");
    }

