    /// AJ2-3 Pro directive test: a missing-source non-stub
    /// external still blocks (the BUILD file doesn't have a
    /// stub marker, so the verifier proceeds with its
    /// strict failure).
    #[test]
    fn aj2_3_missing_source_non_stub_external_still_blocks() {
        use super::detect_external_stub_for_verifier;
        use std::collections::HashMap;
        let tmp = tempfile::TempDir::new().unwrap();
        let repo_root = tmp.path().join("nonstub");
        std::fs::create_dir_all(repo_root.join("pkg")).unwrap();
        std::fs::write(
            repo_root.join("pkg/BUILD"),
            "licenses([\"notice\"])\n\
             cc_library(name = \"x\", srcs = [\"missing.cc\"])\n",
        )
        .unwrap();
        let mut repo_paths = HashMap::new();
        repo_paths.insert("nonstub".to_string(), repo_root.clone());
        // Even though srcs are missing on disk, this is NOT
        // a stub — no marker. The verifier should NOT exempt
        // it.
        let detected =
            detect_external_stub_for_verifier("@nonstub//pkg:x", &repo_paths);
        assert!(detected.is_none());
    }

