    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn same_workspace_commands_are_single_flight_across_clones() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(&workspace_root.join("WORKSPACE"), "")?;
        write_file(
            &workspace_root.join("BUILD.bazel"),
            r#"
config_setting(name = "mode_a", define_values = {"mode": "a"})
config_setting(name = "mode_b", define_values = {"mode": "b"})
filegroup(name = "selected_a")
filegroup(name = "selected_b")
filegroup(
    name = "root_a",
    srcs = select({
        ":mode_a": [":selected_a"],
        "//conditions:default": [":missing_a"],
    }),
)
filegroup(
    name = "root_b",
    srcs = select({
        ":mode_b": [":selected_b"],
        "//conditions:default": [":missing_b"],
    }),
)
"#,
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        let barrier = Arc::new(tokio::sync::Barrier::new(5));
        let first = {
            let orchestrator = orchestrator.clone();
            let barrier = Arc::clone(&barrier);
            let semantics = semantics_with_define(workspace_root, "//:root_a", "mode", "a")?;
            async move {
                barrier.wait().await;
                orchestrator
                    .build_with_dependencies_with_semantics(
                        vec!["//:root_a".to_string()],
                        semantics,
                    )
                    .await
            }
        };
        let second = {
            let orchestrator = orchestrator.clone();
            let barrier = Arc::clone(&barrier);
            let semantics = semantics_with_define(workspace_root, "//:root_b", "mode", "b")?;
            async move {
                barrier.wait().await;
                orchestrator
                    .build_with_dependencies_with_semantics(
                        vec!["//:root_b".to_string()],
                        semantics,
                    )
                    .await
            }
        };
        let third = {
            let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
            let barrier = Arc::clone(&barrier);
            let semantics = semantics_with_define(workspace_root, "//:root_a", "mode", "a")?;
            async move {
                barrier.wait().await;
                orchestrator
                    .build_with_dependencies_with_semantics(
                        vec!["//:root_a".to_string()],
                        semantics,
                    )
                    .await
            }
        };
        let fourth = {
            let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
            let barrier = Arc::clone(&barrier);
            let semantics = semantics_with_define(workspace_root, "//:root_b", "mode", "b")?;
            async move {
                barrier.wait().await;
                orchestrator
                    .build_with_dependencies_with_semantics(
                        vec!["//:root_b".to_string()],
                        semantics,
                    )
                    .await
            }
        };
        let release = async move {
            barrier.wait().await;
        };
        let (first, second, third, fourth, ()) =
            tokio::join!(first, second, third, fourth, release);
        first?;
        second?;
        third?;
        fourth?;
        Ok(())
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn public_test_command_locks_before_target_discovery() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(&workspace_root.join("WORKSPACE"), "")?;
        write_file(
            &workspace_root.join("BUILD.bazel"),
            "filegroup(name = \"not_a_test\")\n",
        )?;

        let held_lock = crate::workspace_command_lock(workspace_root);
        let guard = held_lock.lock().await;
        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        let mut command = Box::pin(orchestrator.test(
            crate::BuildRequest {
                targets: vec!["//:not_a_test".to_string()],
            },
            crate::TestOutputMode::Summary,
            None,
        ));
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(25), &mut command)
                .await
                .is_err(),
            "test discovery started while another same-workspace command held the lock"
        );
        drop(guard);
        let results = tokio::time::timeout(std::time::Duration::from_secs(5), command).await??;
        assert_eq!(results.total(), 0);
        Ok(())
    }

    fn rule_string_list(
        build_file: &rush_parse::BuildFile,
        rule_name: &str,
        attr_name: &str,
    ) -> Vec<String> {
        let rule = build_file
            .rules
            .iter()
            .find(|rule| rule.name == rule_name)
            .unwrap_or_else(|| panic!("missing rule {rule_name}"));
        match rule.attributes.get(attr_name) {
            Some(Value::List(values)) => values
                .iter()
                .map(|value| match value {
                    Value::String(value) => value.clone(),
                    other => panic!(
                        "{rule_name}.{attr_name} contained non-string value: {other:?}"
                    ),
                })
                .collect(),
            other => panic!("missing list attribute {rule_name}.{attr_name}: {other:?}"),
        }
    }

    #[test]
    fn source_discovery_declares_input_files_from_every_select_branch() -> Result<()> {
        let build_file = rush_parse::BuildFile {
            path: PathBuf::from("/workspace/p/BUILD"),
            rules: vec![rush_parse::Rule {
                name: "selected_sources".to_string(),
                rule_type: "cc_library".to_string(),
                attributes: HashMap::from([
                    (
                        "srcs".to_string(),
                        Value::Configurable {
                            op: rush_starlark::ConfigurableOp::Add,
                            left: Box::new(Value::List(vec![Value::String(
                                "base.cc".to_string(),
                            )])),
                            right: Box::new(Value::Select(HashMap::from([
                                (
                                    "//conditions:rush_select_test_never".to_string(),
                                    Value::List(vec![Value::String("inactive.cc".to_string())]),
                                ),
                                (
                                    "//conditions:default".to_string(),
                                    Value::List(vec![Value::String("active.cc".to_string())]),
                                ),
                            ]))),
                        },
                    ),
                    (
                        "hdrs".to_string(),
                        Value::Select(HashMap::from([(
                            "//conditions:rush_select_test_never".to_string(),
                            Value::List(vec![Value::String("unmatched.h".to_string())]),
                        )])),
                    ),
                ]),
            }],
        };

        let names = BuildOrchestrator::package_source_file_target_names(
            &build_file,
            None,
            "p",
        );
        assert!(names.contains("active.cc"));
        assert!(names.contains("inactive.cc"));
        assert!(names.contains("base.cc"));
        assert!(names.contains("unmatched.h"));

        let base = Label::parse("//p:base.cc", None, None)?;
        let active = Label::parse("//p:active.cc", None, None)?;
        let inactive = Label::parse("//p:inactive.cc", None, None)?;
        let unmatched = Label::parse("//p:unmatched.h", None, None)?;
        assert!(BuildOrchestrator::build_file_declares_source_input(
            &build_file,
            &base,
        ));
        assert!(BuildOrchestrator::build_file_declares_source_input(
            &build_file,
            &active,
        ));
        assert!(BuildOrchestrator::build_file_declares_source_input(
            &build_file,
            &inactive,
        ));
        assert!(BuildOrchestrator::build_file_declares_source_input(
            &build_file,
            &unmatched,
        ));
        Ok(())
    }

