    #[test]
    fn scoped_configuration_check_rejects_only_reachable_error_targets() -> Result<()> {
        let good = Label::parse("//p:good", None, None)?;
        let bad = Label::parse("//p:bad", None, None)?;
        let mut graph = DependencyGraph::new();
        graph.add_node(
            good.clone(),
            Box::new(rush_rules::rules_config::IncompatibleTargetInstance::new(
                "good".to_string(),
            )),
        )?;
        graph.add_node(
            bad.clone(),
            Box::new(
                rush_rules::rules_config::UnconfigurableTargetInstance::new(
                    "bad".to_string(),
                    "resolving attribute 'srcs': No matching condition in select() and no default provided"
                        .to_string(),
                ),
            ),
        )?;

        validate_scoped_configuration(&graph, &[good])?;
        let error = validate_scoped_configuration(&graph, &[bad])
            .expect_err("a requested unconfigurable target must fail before analysis");
        let message = format!("{error:#}");
        assert!(message.contains("//p:bad"), "{message}");
        assert!(message.contains("resolving attribute 'srcs'"), "{message}");
        assert!(message.contains("No matching condition in select()"), "{message}");
        Ok(())
    }

    #[test]
    fn scoped_configuration_defers_unsupported_android_siblings() -> Result<()> {
        let host = Label::parse("//p:host", None, None)?;
        let android = Label::parse("//p:mobile", None, None)?;
        let mut registry = rush_rules::registry::RuleRegistry::new();
        tensorflow_rules::register_tensorflow_rules(&mut registry);
        let android_instance = registry
            .get("android_library")
            .expect("TensorFlow registry must retain Android rules")
            .parse_attributes(&HashMap::from([(
                "name".to_string(),
                rush_rules::Value::String("mobile".to_string()),
            )]))?;

        let mut graph = DependencyGraph::new();
        graph.add_node(
            host.clone(),
            Box::new(rush_rules::rules_config::IncompatibleTargetInstance::new(
                "host".to_string(),
            )),
        )?;
        graph.add_node(android.clone(), android_instance)?;

        validate_scoped_configuration(&graph, &[host])?;
        let error = validate_scoped_configuration(&graph, &[android])
            .expect_err("a reachable Android target must fail before analysis");
        let message = format!("{error:#}");
        assert!(message.contains("//p:mobile"), "{message}");
        assert!(message.contains("android_library"), "{message}");
        assert!(message.contains("Android toolchain selection"), "{message}");
        Ok(())
    }

