    async fn assert_registers_source(
        orchestrator: &BuildOrchestrator,
        workspace_root: &Path,
        build_path: &Path,
        label: &str,
        expected_visibility: Option<&[&str]>,
    ) -> Result<()> {
        let label = Label::parse(label, None, None)?;
        let mut graph = DependencyGraph::new();
        assert!(orchestrator.try_register_declared_or_exported_source_file(
            Some(label.package.as_str()),
            &label,
            &mut graph,
            workspace_root,
            build_path,
        )?);
        assert!(graph.has_node(&label));

        let node = graph.get(&label).expect("registered source node");
        assert_eq!(node.rule_instance.rule_type(), "source_file");
        assert_eq!(
            node.rule_instance
                .visibility()
                .map(|visibility| { visibility.iter().map(String::as_str).collect::<Vec<_>>() }),
            expected_visibility.map(|visibility| visibility.to_vec())
        );

        let context = BuildContext::new(
            workspace_root.to_path_buf(),
            workspace_root.join("rush-out"),
        )
        .with_package(PathBuf::from(&label.package));
        let artifacts = node.rule_instance.build(&context).await?;
        assert_eq!(artifacts.len(), 1);
        assert_eq!(artifacts[0].artifact_type, ArtifactType::Source);
        Ok(())
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn source_file_resolution_is_exports_or_declared_inputs_not_disk_only() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();

        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"source_resolution_test\")\n",
        )?;

        write_file(&workspace_root.join("p/positional.h"), "")?;
        write_file(&workspace_root.join("p/keyword.h"), "")?;
        write_file(&workspace_root.join("p/declared.h"), "")?;
        write_file(&workspace_root.join("p/declared.cc"), "")?;
        write_file(&workspace_root.join("p/undeclared.h"), "")?;

        write_file(
            &workspace_root.join("p/BUILD"),
            r#"
exports_files(["positional.h"])

exports_files(
    srcs = ["keyword.h"],
)

cc_library(
    name = "declared_lib",
    srcs = ["declared.cc"],
    hdrs = ["declared.h"],
)

cc_library(
    name = "missing_declared_lib",
    hdrs = ["absent.h"],
)
"#,
        )?;

        write_file(
            &workspace_root.join("q/BUILD"),
            r#"
cc_library(name = "uses_positional", deps = ["//p:positional.h"])
cc_library(name = "uses_keyword", deps = ["//p:keyword.h"])
cc_library(name = "uses_declared", deps = ["//p:declared.h"])
cc_library(name = "uses_undeclared", deps = ["//p:undeclared.h"])
cc_library(name = "uses_absent", deps = ["//p:absent.h"])
"#,
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        // The source-file existence probes now record through the tracked IO and
        // are fail-loud outside a `tracked::scope`; install one on the orchestrator
        // for this unit test (the real path installs it in
        // `build_with_dependencies`). The orchestrator's `with_tracked_scope` then
        // covers `register_package_source_file_targets` /
        // `try_register_declared_or_exported_source_file`, and we scope the direct
        // static-fn calls below the same way.
        orchestrator.ensure_tracked_io();
        let p_build = workspace_root.join("p/BUILD");
        let repo_root = workspace_root.to_path_buf();
        let build_file = orchestrator.parse_build_file_cached(&p_build, Some(&repo_root))?;

        let mut package_graph = DependencyGraph::new();
        for instance in orchestrator.instantiate_build_file(&p_build, Some(&repo_root))? {
            let target_name = instance.target_name().to_string();
            if instance.rule_type() == "source_file"
                && !orchestrator.with_tracked_scope(|| {
                    BuildOrchestrator::source_file_target_exists(workspace_root, "p", &target_name)
                })
            {
                continue;
            }
            package_graph.add_node(
                Label {
                    workspace: None,
                    package: "p".to_string(),
                    target: target_name,
                },
                instance,
            )?;
        }
        orchestrator.register_package_source_file_targets(
            &build_file,
            None,
            "p",
            workspace_root,
            &mut package_graph,
        )?;

        // Pin the direct package-registration fallback as well as normal rule
        // instantiation: recreating a synthetic SourceFileInstance must not
        // discard exports_files visibility metadata.
        let mut synthesized_graph = DependencyGraph::new();
        orchestrator.register_package_source_file_targets(
            &build_file,
            None,
            "p",
            workspace_root,
            &mut synthesized_graph,
        )?;
        assert_eq!(
            synthesized_graph
                .get(&Label::parse("//p:positional.h", None, None)?)
                .and_then(|node| node.rule_instance.visibility()),
            Some(["//visibility:public".to_string()].as_slice())
        );
        assert_eq!(
            synthesized_graph
                .get(&Label::parse("//p:declared.h", None, None)?)
                .and_then(|node| node.rule_instance.visibility()),
            None
        );

        for label in ["//p:positional.h", "//p:keyword.h", "//p:declared.h"] {
            let label = Label::parse(label, None, None)?;
            assert!(
                package_graph.has_node(&label),
                "{} must exist immediately after package load",
                label
            );
        }
        for label in ["//p:undeclared.h", "//p:absent.h"] {
            let label = Label::parse(label, None, None)?;
            assert!(
                !package_graph.has_node(&label),
                "{} must not be registered during package load",
                label
            );
        }

        assert_registers_source(
            &orchestrator,
            workspace_root,
            &p_build,
            "//p:positional.h",
            Some(&["//visibility:public"]),
        )
        .await?;
        assert_registers_source(
            &orchestrator,
            workspace_root,
            &p_build,
            "//p:keyword.h",
            Some(&["//visibility:public"]),
        )
        .await?;
        assert_registers_source(
            &orchestrator,
            workspace_root,
            &p_build,
            "//p:declared.h",
            None,
        )
        .await?;

        let undeclared = Label::parse("//p:undeclared.h", None, None)?;
        let mut graph = DependencyGraph::new();
        assert!(!orchestrator.try_register_declared_or_exported_source_file(
            Some("q"),
            &undeclared,
            &mut graph,
            workspace_root,
            &p_build,
        )?);
        assert!(!graph.has_node(&undeclared));
        assert!(orchestrator.with_tracked_scope(|| {
            BuildOrchestrator::unresolved_label_should_fail(&undeclared, Some(workspace_root))
        }));

        let absent = Label::parse("//p:absent.h", None, None)?;
        let mut graph = DependencyGraph::new();
        let err = orchestrator
            .try_register_declared_or_exported_source_file(
                Some("p"),
                &absent,
                &mut graph,
                workspace_root,
                &p_build,
            )
            .expect_err("declared but absent source file must fail");
        assert!(
            err.to_string().contains("not found on disk"),
            "unexpected error: {err:#}"
        );

        Ok(())
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn exports_files_visibility_controls_cross_package_source_access() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(&workspace_root.join("WORKSPACE"), "")?;
        for file in [
            "omitted.txt",
            "none.txt",
            "empty.txt",
            "private.txt",
            "grant.txt",
        ] {
            write_file(&workspace_root.join("producer").join(file), file)?;
        }
        write_file(
            &workspace_root.join("producer/BUILD"),
            r#"
package(default_visibility = ["//visibility:private"])
exports_files(["omitted.txt"])
native.exports_files(["none.txt"], visibility = None)
exports_files(["empty.txt"], visibility = [])
exports_files(["private.txt"], visibility = ["//visibility:private"])
exports_files(["grant.txt"], visibility = ["//consumer:__pkg__"])
"#,
        )?;
        write_file(
            &workspace_root.join("consumer/BUILD"),
            r#"
filegroup(name = "use_omitted", srcs = ["//producer:omitted.txt"])
filegroup(name = "use_none", srcs = ["//producer:none.txt"])
filegroup(name = "use_empty", srcs = ["//producer:empty.txt"])
filegroup(name = "use_private", srcs = ["//producer:private.txt"])
filegroup(name = "use_grant", srcs = ["//producer:grant.txt"])
"#,
        )?;

        BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
            .build_with_dependencies(vec![
                "//consumer:use_omitted".to_string(),
                "//consumer:use_none".to_string(),
                "//consumer:use_grant".to_string(),
            ])
            .await?;

        for (target, denial) in [
            ("use_empty", "is not visible"),
            ("use_private", "has private visibility"),
        ] {
            let error = BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
                .build_with_dependencies(vec![format!("//consumer:{target}")])
                .await
                .expect_err("restricted exported source must deny cross-package access");
            let message = format!("{error:#}");
            assert!(message.contains(denial), "{message}");
            assert!(
                message.contains(&format!(
                    "//producer:{}.txt",
                    target.trim_start_matches("use_")
                )),
                "{message}"
            );
        }
        Ok(())
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn loaded_package_rejects_malformed_package_group_attributes() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(&workspace_root.join("WORKSPACE"), "")?;

        let invalid_packages = [
            (
                "bad_packages",
                r#"
package_group(
    name = "bad",
    packages = select({"//conditions:default": ["//consumer"]}),
)
filegroup(name = "good_sibling", srcs = [])
"#,
                "in call to package_group(), parameter 'packages' got value of type 'select', want 'sequence'",
            ),
            (
                "bad_includes",
                r#"
package_group(
    name = "bad",
    packages = ["//consumer"],
    includes = [] + select({"//conditions:default": []}),
)
filegroup(name = "good_sibling", srcs = [])
"#,
                "in call to package_group(), parameter 'includes' got value of type 'select', want 'sequence'",
            ),
            (
                "bad_int",
                r#"
package_group(name = "bad", packages = 7)
filegroup(name = "good_sibling", srcs = [])
"#,
                "in call to package_group(), parameter 'packages' got value of type 'int', want 'sequence'",
            ),
            (
                "bad_none",
                r#"
package_group(name = "bad", includes = None)
filegroup(name = "good_sibling", srcs = [])
"#,
                "in call to package_group(), parameter 'includes' got value of type 'NoneType', want 'sequence'",
            ),
            (
                "bad_element",
                r#"
package_group(name = "bad", packages = ["//consumer", 7])
filegroup(name = "good_sibling", srcs = [])
"#,
                "expected value of type 'string' for element 1 of 'package_group.packages argument', but got 7 (int)",
            ),
            (
                "bad_nested",
                r#"
package_group(
    name = "bad",
    includes = [select({"//conditions:default": "//owner:group"})],
)
filegroup(name = "good_sibling", srcs = [])
"#,
                "expected value of type 'string' for element 0 of 'package_group.includes argument', but got select({\"//conditions:default\": \"//owner:group\"}) (select)",
            ),
            (
                "bad_dict",
                r#"
package_group(
    name = "bad",
    packages = {"key": select({"//conditions:default": "//consumer"})},
)
filegroup(name = "good_sibling", srcs = [])
"#,
                "in call to package_group(), parameter 'packages' got value of type 'dict', want 'sequence'",
            ),
        ];
        for (package, source, _) in invalid_packages {
            write_file(&workspace_root.join(package).join("BUILD"), source)?;
        }

        write_file(
            &workspace_root.join("bad_macro/defs.bzl"),
            r#"
def malformed_group():
    native.package_group(
        name = "bad",
        includes = [] + select({"//conditions:default": []}),
    )
"#,
        )?;
        write_file(
            &workspace_root.join("bad_macro/BUILD"),
            r#"
load(":defs.bzl", "malformed_group")
malformed_group()
filegroup(name = "good_sibling", srcs = [])
"#,
        )?;
        write_file(
            &workspace_root.join("good/BUILD"),
            "filegroup(name = \"other_package\", srcs = [])\n",
        )?;
        write_file(
            &workspace_root.join("valid/BUILD"),
            r#"
package_group(
    name = "constant",
    packages = ["//consumer"] + ["//friend"],
    includes = (),
)
package_group(
    name = "dead_select",
    packages = [] if True else select({"//conditions:default": ["//consumer"]}),
)
filegroup(name = "good_sibling", srcs = [])
"#,
        )?;

        BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
            .build_with_dependencies(vec!["//good:other_package".to_string()])
            .await?;
        BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
            .build_with_dependencies(vec!["//valid:good_sibling".to_string()])
            .await?;

        for (package, _, expected) in invalid_packages {
            for target in ["bad", "good_sibling"] {
                let error = BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
                    .build_with_dependencies(vec![format!("//{package}:{target}")])
                    .await
                    .expect_err(
                        "a selected or sibling package_group load error must reject the package",
                    );
                let message = format!("{error:#}");
                assert!(message.ends_with(expected), "{message}");
                assert!(!message.contains("cannot be configured"), "{message}");
            }
        }

        let macro_error = BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
            .build_with_dependencies(vec!["//bad_macro:good_sibling".to_string()])
            .await
            .expect_err("a malformed package_group emitted by a macro must reject the package");
        let message = format!("{macro_error:#}");
        assert!(
            message.ends_with(
                "in call to package_group(), parameter 'includes' got value of type 'select', want 'sequence'"
            ),
            "{message}"
        );
        Ok(())
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn explicit_source_path_rejects_build_and_build_bazel_subpackages() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);

        for boundary_file in ["BUILD", "BUILD.bazel"] {
            let temp = TempDir::new()?;
            let workspace_root = temp.path();
            write_file(
                &workspace_root.join("WORKSPACE"),
                "workspace(name = \"subpackage_boundary_test\")\n",
            )?;
            write_file(&workspace_root.join("p/sub/f.txt"), "owned by //p/sub\n")?;
            write_file(
                &workspace_root.join("p/sub").join(boundary_file),
                "filegroup(name = \"owned\", srcs = [\"f.txt\"])\n",
            )?;
            write_file(
                &workspace_root.join("p/BUILD"),
                "filegroup(name = \"root\", srcs = [\"sub/f.txt\"])\n",
            )?;

            let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
            let error = orchestrator
                .build_with_dependencies(vec!["//p:root".to_string()])
                .await
                .expect_err("an explicit source path must not cross a subpackage boundary");
            let message = format!("{error:#}");
            assert!(
                message.contains("source file label //p:sub/f.txt crosses package boundary"),
                "unexpected error for {boundary_file}: {message}"
            );
            assert!(
                message.contains("//p/sub"),
                "error must identify the owning subpackage for {boundary_file}: {message}"
            );
        }

        Ok(())
    }

