        write_file(
            &workspace_root.join("p/BUILD"),
            r#"
filegroup(name = "ordinary", srcs = ["dir/local.txt"])
filegroup(name = "qualified", srcs = ["//p/sub:owned.txt"])
"#,
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        orchestrator
