    #[tokio::test(flavor = "multi_thread")]
    async fn full_parser_glob_prunes_nested_packages_for_all_pattern_shapes() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"glob_boundary_test\")\n",
        )?;
        write_file(&workspace_root.join("a/top.cc"), "")?;
        write_file(&workspace_root.join("a/ordinary/keep.cc"), "")?;
        write_file(&workspace_root.join("a/sub/drop.cc"), "")?;
        write_file(&workspace_root.join("a/sub/deeper/drop.cc"), "")?;
        write_file(
            &workspace_root.join("a/sub/BUILD"),
            "filegroup(name = \"owned\")\n",
        )?;
        write_file(&workspace_root.join("a/bazel_sub/drop.cc"), "")?;
        write_file(
            &workspace_root.join("a/bazel_sub/BUILD.bazel"),
            "filegroup(name = \"owned\")\n",
        )?;
        let build_path = workspace_root.join("a/BUILD");
        write_file(
            &build_path,
            r#"
filegroup(name = "recursive", srcs = glob(["**/*.cc"]))
filegroup(name = "literal_build", srcs = glob(["sub/*.cc"]))
filegroup(name = "literal_build_bazel", srcs = native.glob(["bazel_sub/*.cc"]))
filegroup(name = "ordinary", srcs = glob(["ordinary/*.cc"]))
"#,
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        orchestrator.ensure_tracked_io();
        let repo_root = workspace_root.to_path_buf();
        let build_file = orchestrator.parse_build_file_cached(&build_path, Some(&repo_root))?;

        assert_eq!(
            rule_string_list(&build_file, "recursive", "srcs"),
            vec!["ordinary/keep.cc".to_string(), "top.cc".to_string()]
        );
        assert!(rule_string_list(&build_file, "literal_build", "srcs").is_empty());
        assert!(
            rule_string_list(&build_file, "literal_build_bazel", "srcs").is_empty()
        );
        assert_eq!(
            rule_string_list(&build_file, "ordinary", "srcs"),
            vec!["ordinary/keep.cc".to_string()]
        );
        Ok(())
    }

    #[derive(Clone, Copy)]
    enum MarkerChange {
        Add,
        Remove,
    }

    async fn assert_cached_glob_refreshes(external: bool, change: MarkerChange) -> Result<()> {
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"glob_marker_cache_test\")\n",
        )?;
        let repo_root = if external {
            workspace_root.join("external_repo")
        } else {
            workspace_root.to_path_buf()
        };
        write_file(&repo_root.join("a/top.cc"), "")?;
        write_file(&repo_root.join("a/sub/nested.cc"), "")?;
        let marker = match change {
            MarkerChange::Add => repo_root.join("a/sub/BUILD"),
            MarkerChange::Remove => repo_root.join("a/sub/BUILD.bazel"),
        };
        if matches!(change, MarkerChange::Remove) {
            write_file(&marker, "filegroup(name = \"owned\")\n")?;
        }
        let build_path = repo_root.join("a/BUILD");
        write_file(
            &build_path,
            "filegroup(name = \"globbed\", srcs = glob([\"**/*.cc\"]))\n",
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        if external {
            orchestrator
                .external_repo_paths
                .lock()
                .await
                .insert("repo".to_string(), repo_root.clone());
            orchestrator
                .bzl_loader
                .lock()
                .expect("BzlLoader lock")
                .add_external_repo("repo".to_string(), repo_root.clone());
        }

        let with_nested = vec!["sub/nested.cc".to_string(), "top.cc".to_string()];
        let without_nested = vec!["top.cc".to_string()];
        let (first_expected, second_expected) = match change {
            MarkerChange::Add => (&with_nested, &without_nested),
            MarkerChange::Remove => (&without_nested, &with_nested),
        };

        let first_io = orchestrator.install_fresh_tracked_io_for_test();
        let first = orchestrator.parse_build_file_cached(&build_path, Some(&repo_root))?;
        assert_eq!(rule_string_list(&first, "globbed", "srcs"), *first_expected);
        let first_manifest = first_io.manifest();
        assert!(first_manifest.deps().iter().any(|dep| {
            matches!(dep, Dependency::DirListing { path, .. } if path == &repo_root.join("a/sub"))
        }));

        match change {
            MarkerChange::Add => write_file(&marker, "filegroup(name = \"owned\")\n")?,
            MarkerChange::Remove => std::fs::remove_file(&marker)?,
        }
        assert!(matches!(
            first_manifest
                .validate(&rush_command_core::CommandSemantics::from_process())
                .staleness,
            Staleness::Stale { .. }
        ));

        let second_io = orchestrator.install_fresh_tracked_io_for_test();
        let second = orchestrator.parse_build_file_cached(&build_path, Some(&repo_root))?;
        assert!(!Arc::ptr_eq(&first, &second));
        assert_eq!(
            rule_string_list(&second, "globbed", "srcs"),
            *second_expected,
            "{} repository reused the pre-change glob expansion",
            if external { "external" } else { "main" }
        );
        assert_eq!(
            second_io
                .manifest()
                .validate(&rush_command_core::CommandSemantics::from_process())
                .staleness,
            Staleness::Fresh
        );

        let third_io = orchestrator.install_fresh_tracked_io_for_test();
        let third = orchestrator.parse_build_file_cached(&build_path, Some(&repo_root))?;
        assert!(Arc::ptr_eq(&second, &third));
        let third_manifest = third_io.manifest();
        assert!(third_manifest.deps().iter().any(|dep| {
            matches!(dep, Dependency::DirListing { path, .. } if path == &repo_root.join("a/sub"))
        }));
        assert_eq!(
            third_manifest
                .validate(&rush_command_core::CommandSemantics::from_process())
                .staleness,
            Staleness::Fresh
        );
        Ok(())
    }

