    #[tokio::test(flavor = "multi_thread")]
    async fn external_repo_glob_and_explicit_sources_honor_its_package_boundaries() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        let external_root = workspace_root.join("external_repo");
        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"external_boundary_test\")\n",
        )?;
        write_file(
            &workspace_root.join("p/BUILD"),
            "filegroup(name = \"root\", srcs = [\"@repo//a:bad\"])\n",
        )?;
        write_file(&external_root.join("a/top.cc"), "")?;
        write_file(&external_root.join("a/ordinary/keep.cc"), "")?;
        write_file(&external_root.join("a/sub/f.txt"), "")?;
        write_file(&external_root.join("a/sub/drop.cc"), "")?;
        write_file(
            &external_root.join("a/sub/BUILD"),
            "filegroup(name = \"owned\")\n",
        )?;
        let external_build = external_root.join("a/BUILD");
        write_file(
            &external_build,
            r#"
filegroup(name = "bad", srcs = ["sub/f.txt"])
filegroup(name = "globbed", srcs = glob(["**/*.cc"]))
"#,
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        orchestrator
            .external_repo_paths
            .lock()
            .await
            .insert("repo".to_string(), external_root.clone());
        orchestrator
            .bzl_loader
            .lock()
            .expect("BzlLoader lock")
            .add_external_repo("repo".to_string(), external_root.clone());
        orchestrator.ensure_tracked_io();

        let build_file =
            orchestrator.parse_build_file_cached(&external_build, Some(&external_root))?;
        assert_eq!(
            rule_string_list(&build_file, "globbed", "srcs"),
            vec!["ordinary/keep.cc".to_string(), "top.cc".to_string()]
        );

        let error = orchestrator
            .build_with_dependencies(vec!["//p:root".to_string()])
            .await
            .expect_err("external source paths must honor the external repo boundary");
        let message = format!("{error:#}");
        assert!(
            message.contains(
                "source file label @repo//a:sub/f.txt crosses package boundary into @repo//a/sub"
            ),
            "unexpected error: {message}"
        );
        Ok(())
    }

    async fn assert_unresolved_main_dependency_fails(
        dependency: &str,
        dependency_build: Option<(&str, &str)>,
    ) -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();

        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"undefined_dep_test\")\n",
        )?;
        write_file(
            &workspace_root.join("p/BUILD"),
            &format!(
                "cc_library(name = \"root\", deps = [\"{}\"])\n",
                dependency
            ),
        )?;
        if let Some((package, contents)) = dependency_build {
            write_file(&workspace_root.join(package).join("BUILD"), contents)?;
        }

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        let error = orchestrator
            .build_with_dependencies(vec!["//p:root".to_string()])
            .await
            .expect_err("an unresolved main-repository dependency must fail");
        let message = format!("{error:#}");
        let expected_dependency = dependency
            .strip_prefix("@undefined_dep_test//")
            .or_else(|| dependency.strip_prefix("@//"))
            .or_else(|| dependency.strip_prefix("@@//"))
            .map(|suffix| format!("//{suffix}"))
            .unwrap_or_else(|| dependency.to_string());
        assert!(
            message.contains(&expected_dependency),
            "error must identify {expected_dependency}: {message}"
        );
        assert!(
            message.contains("doesn't exist in the graph"),
            "unexpected error: {message}"
        );
        Ok(())
    }

