    #[tokio::test(flavor = "multi_thread")]
    async fn unresolved_external_non_file_label_keeps_compatibility_fallback() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let orchestrator = BuildOrchestrator::with_workspace(temp.path().to_path_buf());
        orchestrator.ensure_tracked_io();

        let external = Label::parse("@repo//q:missing", None, None)?;
        assert!(!orchestrator.with_tracked_scope(|| {
            BuildOrchestrator::unresolved_label_should_fail(
                &external,
                Some(temp.path()),
            )
        }));

        let external_file = Label::parse("@repo//q:missing.h", None, None)?;
        assert!(orchestrator.with_tracked_scope(|| {
            BuildOrchestrator::unresolved_label_should_fail(
                &external_file,
                Some(temp.path()),
            )
        }));

        let explicit_main = Label::parse("@//q:missing", None, None)?;
        assert!(orchestrator.with_tracked_scope(|| {
            BuildOrchestrator::unresolved_label_should_fail(
                &explicit_main,
                Some(temp.path()),
            )
        }));

        let canonical_root = Label::parse("@@//q:missing", None, None)?;
        assert!(orchestrator.with_tracked_scope(|| {
            BuildOrchestrator::unresolved_label_should_fail(
                &canonical_root,
                Some(temp.path()),
            )
        }));
        Ok(())
    }

