    #[cfg(target_arch = "x86_64")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn concurrent_consumers_wait_for_macro_condition_package_registration() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path().to_path_buf();
        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"condition_registration_race_test\")\n",
        )?;
        write_file(
            &workspace_root.join("cfg/defs.bzl"),
            r#"
def declare_host():
    total = 0
    for value in range(20000):
        total += value
    native.config_setting(
        name = "host",
        values = {"cpu": "k8"},
        visibility = ["//visibility:public"],
    )
"#,
        )?;
        write_file(
            &workspace_root.join("cfg/BUILD"),
            "load(\":defs.bzl\", \"declare_host\")\ndeclare_host()\n",
        )?;
        let app_build = workspace_root.join("app/BUILD");
        write_file(
            &app_build,
            r#"
filegroup(name = "selected")
filegroup(name = "missing_a")
filegroup(name = "missing_b")
filegroup(name = "a", srcs = select({"//cfg:host": [":selected"], "//conditions:default": [":missing_a"]}))
filegroup(name = "b", srcs = select({"//cfg:host": [":selected"], "//conditions:default": [":missing_b"]}))
"#,
        )?;

        let orchestrator = std::sync::Arc::new(BuildOrchestrator::with_workspace(
            workspace_root.clone(),
        ));
        orchestrator.ensure_tracked_io();
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(2));
        let mut tasks = Vec::new();
        for target in ["a", "b"] {
            let orchestrator = std::sync::Arc::clone(&orchestrator);
            let barrier = std::sync::Arc::clone(&barrier);
            let app_build = app_build.clone();
            let workspace_root = workspace_root.clone();
            let target = target.to_string();
            tasks.push(tokio::task::spawn_blocking(move || -> Result<Vec<String>> {
                barrier.wait();
                let target_names = HashSet::from([target.clone()]);
                let instances = orchestrator.instantiate_build_file_for_repository_targets(
                    &app_build,
                    Some(&workspace_root),
                    None,
                    &target_names,
                )?;
                Ok(instances
                    .iter()
                    .find(|instance| instance.target_name() == target)
                    .expect("configured consumer")
                    .dependencies())
            }));
        }
        for task in tasks {
            assert_eq!(task.await??, vec![":selected"]);
        }
        Ok(())
    }

