    #[cfg(any(
        all(target_os = "linux", target_arch = "x86_64"),
        all(target_os = "linux", target_arch = "aarch64"),
        all(target_os = "macos", target_arch = "aarch64")
    ))]
    #[tokio::test(flavor = "multi_thread")]
    async fn modular_pycross_environment_alias_keeps_default_host_selection() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        let environments_root = workspace_root.join("environments_repo");
        let environments_repository =
            "rules_pycross++environments+rules_pycross_all_environments";
        let host_triple = if cfg!(all(target_os = "linux", target_arch = "x86_64")) {
            "x86_64-unknown-linux-gnu"
        } else if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
            "aarch64-unknown-linux-gnu"
        } else {
            "aarch64-apple-darwin"
        };
        let environment_name = format!("_env_python_3.13_{host_triple}");
        let alternate_environment_name =
            format!("_env_python_3.12_{host_triple}");
        let gpu_environment_name = format!("{environment_name}_nvidia_gpu");

        write_file(&workspace_root.join("WORKSPACE"), "")?;
        write_file(
            &environments_root.join("WORKSPACE"),
            "workspace(name = \"environments\")\n",
        )?;
        write_file(
            &environments_root.join("BUILD.bazel"),
            r#"
config_setting(
    name = "inner_python_config",
    flag_values = {":interpreter_version": "3.13"},
)
alias(
    name = "python_environment_config",
    actual = select({
        ":inner_python_config": ":inner_python_config",
        "//conditions:default": ":inner_python_config",
    }),
    visibility = ["//visibility:public"],
)
"#,
        )?;
        write_file(
            &workspace_root.join("pycross/BUILD.bazel"),
            &format!(
                "alias(\n    name = \"{environment_name}\",\n    actual = \"@@{environments_repository}//:python_environment_config\",\n    visibility = [\"//visibility:public\"],\n)\n\
                 alias(\n    name = \"{alternate_environment_name}\",\n    actual = \"@@{environments_repository}//:python_environment_config\",\n    visibility = [\"//visibility:public\"],\n)\n\
                 alias(\n    name = \"{gpu_environment_name}\",\n    actual = \"@@{environments_repository}//:python_environment_config\",\n    visibility = [\"//visibility:public\"],\n)\n"
            ),
        )?;
        write_file(
            &workspace_root.join("bad_flag/BUILD.bazel"),
            r#"
config_setting(
    name = "inner_python_config",
    flag_values = {":interpreter_version": "3.13"},
    visibility = ["//visibility:public"],
)
"#,
        )?;
        write_file(
            &workspace_root.join("bad_pycross/BUILD.bazel"),
            &format!(
                "alias(\n    name = \"{environment_name}\",\n    actual = \"//app:selected\",\n    visibility = [\"//visibility:public\"],\n)\n"
            ),
        )?;
        write_file(
            &workspace_root.join("bad_flag_pycross/BUILD.bazel"),
            &format!(
                "alias(\n    name = \"{environment_name}\",\n    actual = \"//bad_flag:inner_python_config\",\n    visibility = [\"//visibility:public\"],\n)\n"
            ),
        )?;
        write_file(
            &workspace_root.join("app/BUILD.bazel"),
            &format!(
                r#"
filegroup(name = "selected", visibility = ["//visibility:public"])
filegroup(name = "fallback")
filegroup(
    name = "root",
    srcs = select({{
        "//pycross:{environment_name}": [":selected"],
        "//conditions:default": [":missing"],
    }}),
)
filegroup(
    name = "alternate_root",
    srcs = select({{
        "//pycross:{alternate_environment_name}": [":selected"],
        "//conditions:default": [":missing"],
    }}),
)
filegroup(
    name = "bad_root",
    srcs = select({{
        "//bad_pycross:{environment_name}": [":selected"],
        "//conditions:default": [":fallback"],
    }}),
)
filegroup(
    name = "bad_flag_root",
    srcs = select({{
        "//bad_flag_pycross:{environment_name}": [":selected"],
        "//conditions:default": [":fallback"],
    }}),
)
filegroup(
    name = "gpu_root",
    srcs = select({{
        "//pycross:{gpu_environment_name}": [":selected"],
        "//conditions:default": [":fallback"],
    }}),
)
"#
            ),
        )?;

        let orchestrator = BuildOrchestrator::with_workspace(workspace_root.to_path_buf());
        orchestrator
            .external_repo_paths
            .lock()
            .await
            .insert(environments_repository.to_string(), environments_root.clone());
        orchestrator
            .bzl_loader
            .lock()
            .expect("BzlLoader lock")
            .add_external_repo(environments_repository.to_string(), environments_root);
        orchestrator
            .build_with_dependencies_with_semantics(
                vec!["//app:root".to_string()],
                semantics_with_environment(workspace_root, "//app:root", &[])?,
            )
            .await?;
        orchestrator
            .build_with_dependencies_with_semantics(
                vec!["//app:alternate_root".to_string()],
                semantics_with_environment(
                    workspace_root,
                    "//app:alternate_root",
                    &[("RUSH_PY_VERSION", "3_12")],
                )?,
            )
            .await?;
        let bad_alias = orchestrator
            .build_with_dependencies_with_semantics(
                vec!["//app:bad_root".to_string()],
                semantics_with_environment(workspace_root, "//app:bad_root", &[])?,
            )
            .await
            .expect_err("a generated-looking alias to an ordinary target must fail type validation");
        assert!(
            format!("{bad_alias:#}").contains("not a config_setting or constraint_value"),
            "{bad_alias:#}"
        );
        let arbitrary_flag_alias = orchestrator
            .build_with_dependencies_with_semantics(
                vec!["//app:bad_flag_root".to_string()],
                semantics_with_environment(workspace_root, "//app:bad_flag_root", &[])?,
            )
            .await
            .expect_err("matching-name aliases outside the canonical pycross environments repo must fail closed");
        assert!(
            format!("{arbitrary_flag_alias:#}")
                .contains("does not yet support non-empty config_setting.flag_values"),
            "{arbitrary_flag_alias:#}"
        );
        let gpu_alias = orchestrator
            .build_with_dependencies_with_semantics(
                vec!["//app:gpu_root".to_string()],
                semantics_with_environment(workspace_root, "//app:gpu_root", &[])?,
            )
            .await
            .expect_err("GPU pycross aliases must not inherit the base-host flag_values bridge");
        assert!(
            format!("{gpu_alias:#}")
                .contains("does not yet support non-empty config_setting.flag_values"),
            "{gpu_alias:#}"
        );
        let inner = orchestrator
            .build_with_dependencies_with_semantics(
                vec![format!("@{environments_repository}//:inner_python_config")],
                semantics_with_environment(
                    workspace_root,
                    &format!("@{environments_repository}//:inner_python_config"),
                    &[],
                )?,
            )
            .await
            .expect_err("direct use of the unsupported inner flag condition must still fail");
        assert!(
            format!("{inner:#}")
                .contains("does not yet support non-empty config_setting.flag_values"),
            "{inner:#}"
        );
        Ok(())
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn constraint_value_semantic_errors_are_configured_closure_scoped() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);
        let temp = TempDir::new()?;
        let workspace_root = temp.path();
        write_file(
            &workspace_root.join("WORKSPACE"),
            "workspace(name = \"constraint_metadata_test\")\n",
        )?;
        write_file(
            &workspace_root.join("metadata/BUILD.bazel"),
            r#"
filegroup(name = "ordinary", visibility = ["//visibility:public"])
constraint_setting(name = "setting", visibility = ["//visibility:public"])
alias(
    name = "setting_alias",
    actual = ":setting",
    visibility = ["//visibility:public"],
)
constraint_value(
    name = "good",
    constraint_setting = ":setting_alias",
    visibility = ["//visibility:public"],
)
constraint_value(
    name = "bad",
    constraint_setting = ":ordinary",
    visibility = ["//visibility:public"],
)
constraint_value(
    name = "one",
    constraint_setting = ":setting",
    visibility = ["//visibility:public"],
)
constraint_value(
    name = "two",
    constraint_setting = ":setting_alias",
    visibility = ["//visibility:public"],
)
config_setting(
    name = "duplicate",
    constraint_values = [":two", ":one"],
    visibility = ["//visibility:public"],
)
"#,
        )?;
        write_file(
            &workspace_root.join("app/BUILD.bazel"),
            r#"
filegroup(name = "root")
filegroup(name = "selected")
filegroup(name = "fallback")
filegroup(
    name = "bad_consumer",
    srcs = select({
        "//metadata:bad": [":selected"],
        "//conditions:default": [":fallback"],
    }),
)
filegroup(
    name = "duplicate_consumer",
    srcs = select({
        "//metadata:duplicate": [":selected"],
        "//conditions:default": [":fallback"],
    }),
)
"#,
        )?;

        BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
            .build_with_dependencies(vec!["//app:root".to_string()])
            .await?;
        BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
            .build_with_dependencies(vec!["//metadata:good".to_string()])
            .await?;

        for target in ["//metadata:bad", "//app:bad_consumer"] {
            let error = BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
                .build_with_dependencies(vec![target.to_string()])
                .await
                .expect_err("wrong constraint_setting type must fail in analysis");
            let message = format!("{error:#}");
            assert!(message.contains("not a constraint_setting"), "{target}: {message}");
        }
        for target in ["//metadata:duplicate", "//app:duplicate_consumer"] {
            let error = BuildOrchestrator::with_workspace(workspace_root.to_path_buf())
                .build_with_dependencies(vec![target.to_string()])
                .await
                .expect_err("duplicate setting identities must fail in analysis");
            let message = format!("{error:#}");
            assert!(message.contains("duplicate constraint values"), "{target}: {message}");
            assert!(message.contains("//metadata:one"), "{target}: {message}");
            assert!(message.contains("//metadata:two"), "{target}: {message}");
        }
        Ok(())
    }

