    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "multi_thread")]
    async fn identical_condition_labels_are_isolated_between_workspaces() -> Result<()> {
        once_cell::sync::Lazy::force(&TEST_CLONE_CACHE);

        let host_workspace = TempDir::new()?;
        let other_workspace = TempDir::new()?;
        for (root, os) in [
            (host_workspace.path(), "linux"),
            (other_workspace.path(), "windows"),
        ] {
            write_file(
                &root.join("WORKSPACE"),
                "workspace(name = \"condition_scope_test\")\n",
            )?;
            write_file(
                &root.join("platforms/os/BUILD.bazel"),
                r#"
constraint_setting(name = "os", visibility = ["//visibility:public"])
constraint_value(name = "linux", constraint_setting = ":os", visibility = ["//visibility:public"])
constraint_value(name = "windows", constraint_setting = ":os", visibility = ["//visibility:public"])
"#,
            )?;
            write_file(
                &root.join("conditions/BUILD"),
                &format!(
                    "config_setting(\n\
                     name = \"workspace_isolation_probe\",\n\
                     constraint_values = [\"@platforms//os:{os}\"],\n\
                     visibility = [\"//visibility:public\"],\n\
                     )\n"
                ),
            )?;
            write_file(
                &root.join("app/BUILD"),
                r#"
filegroup(name = "selected")
filegroup(name = "fallback")
filegroup(
    name = "root",
    srcs = select({
        "//conditions:workspace_isolation_probe": [":selected"],
        "//conditions:default": [":fallback"],
    }),
)
"#,
            )?;
        }

        let host_root = host_workspace.path().to_path_buf();
        let other_root = other_workspace.path().to_path_buf();
        let host = BuildOrchestrator::with_workspace(host_root.clone());
        let other = BuildOrchestrator::with_workspace(other_root.clone());
        for (orchestrator, root) in [(&host, &host_root), (&other, &other_root)] {
            let platforms_root = root.join("platforms");
            orchestrator
                .external_repo_paths
                .lock()
                .await
                .insert("platforms".to_string(), platforms_root.clone());
            orchestrator
                .bzl_loader
                .lock()
                .expect("BzlLoader lock")
                .add_external_repo("platforms".to_string(), platforms_root);
        }
        host.ensure_tracked_io();
        other.ensure_tracked_io();

        let selected_dep = |orchestrator: &BuildOrchestrator, root: &PathBuf| -> Result<Vec<String>> {
            let instances = orchestrator.instantiate_build_file(
                &root.join("app/BUILD"),
                Some(root),
            )?;
            Ok(instances
                .iter()
                .find(|instance| instance.target_name() == "root")
                .expect("root instance")
                .dependencies())
        };

        assert_eq!(selected_dep(&host, &host_root)?, vec![":selected"]);
        assert_eq!(selected_dep(&other, &other_root)?, vec![":fallback"]);
        assert_eq!(
            selected_dep(&host, &host_root)?,
            vec![":selected"],
            "registering the same label in another workspace must not deactivate it"
        );
        assert!(
            !rush_starlark::config_defines::with_configuration_scope("", || {
                rush_starlark::config_defines::is_active_config_setting(
                    "//conditions:workspace_isolation_probe",
                )
            }),
            "condition metadata leaked into the empty compatibility scope"
        );
        Ok(())
    }

    #[tokio::test(flavor = "multi_thread")]
